function resizeCells(cells:Array<string|null>,oldW:number,oldH:number,newW:number,newH:number,anchorX:-1|0|1=-1,anchorY:-1|0|1=-1){const next=Array<string|null>(newW*newH).fill(null),dx=anchorX===-1?0:anchorX===0?Math.floor((newW-oldW)/2):newW-oldW,dy=anchorY===-1?0:anchorY===0?Math.floor((newH-oldH)/2):newH-oldH;for(let y=0;y<oldH;y++)for(let x=0;x<oldW;x++){const nx=x+dx,ny=y+dy;if(nx>=0&&ny>=0&&nx<newW&&ny<newH)next[ny*newW+nx]=cells[y*oldW+x]}return next}
