function download(blob:Blob,name:string){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
function selectImage(){fileInput.value?.click()}
function resetCrop(){cropZoom.value=1;cropX.value=0;cropY.value=0}
function cropStart(e:PointerEvent){cropDragging=true;cropPointerX=e.clientX;cropPointerY=e.clientY;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)}
function cropMove(e:PointerEvent){if(!cropDragging)return;const rect=(e.currentTarget as HTMLElement).getBoundingClientRect();cropX.value=Math.max(-1,Math.min(1,cropX.value+(e.clientX-cropPointerX)/rect.width*2*cropZoom.value));cropY.value=Math.max(-1,Math.min(1,cropY.value+(e.clientY-cropPointerY)/rect.height*2*cropZoom.value));cropPointerX=e.clientX;cropPointerY=e.clientY}
function cropStop(){cropDragging=false}
function loadFile(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;if(pendingImageUrl.value)URL.revokeObjectURL(pendingImageUrl.value);pendingImageUrl.value=URL.createObjectURL(file);pendingImageName.value=file.name.replace(/\.[^.]+$/,'')||'导入图片';generatedLayerName.value=pendingImageName.value;convertWidth.value=Math.min(180,project.value?.width??52);importDraft.value=null;resetCrop();importMenuOpen.value=true;input.value=''}
function saveImportedCrop(){if(!importDraft.value||!project.value||!rawProject.value)return;const draft=importDraft.value,cw=Math.max(1,Math.round(draft.width/cropZoom.value)),ch=Math.max(1,Math.round(draft.height/cropZoom.value)),sx=Math.round((draft.width-cw)*(cropX.value+1)/2),sy=Math.round((draft.height-ch)*(cropY.value+1)/2),cropped=Array<string|null>(cw*ch).fill(null);for(let y=0;y<ch;y++)for(let x=0;x<cw;x++)cropped[y*cw+x]=draft.cells[(sy+y)*draft.width+sx+x];const canvasWidth=Math.max(project.value.width,cw),canvasHeight=Math.max(project.value.height,ch),cells=Array<string|null>(canvasWidth*canvasHeight).fill(null);cropped.forEach((cell,index)=>cells[Math.floor(index/cw)*canvasWidth+index%cw]=cell);const resized=layers.value.map(layer=>({...layer,cells:resizeCells(layer.cells,project.value!.width,project.value!.height,canvasWidth,canvasHeight)})),used=new Set(cropped.filter(Boolean)).size,layer:ProjectLayer={id:crypto.randomUUID(),name:`${used} 色-${generatedLayerName.value.trim()||pendingImageName.value||'导入图纸'}`,type:'bead',visible:true,locked:false,opacity:1,cells};saveLayers([...resized,layer],layer.id,canvasWidth,canvasHeight);widthDraft.value=canvasWidth;heightDraft.value=canvasHeight;importDraft.value=null;importMenuOpen.value=false;showToast(`已按拼豆预览剪裁并生成 ${used} 色图层`)}
function rgbOf(hex:string){const value=parseInt(hex.slice(1),16);return[value>>16,(value>>8)&255,value&255]}
function readableColor(hex:string){const [r,g,b]=rgbOf(hex);return r*.299+g*.587+b*.114<150?'#fff':'#302b28'}
function distance(a:number[],b:number[]){return(a[0]-b[0])**2+(a[1]-b[1])**2+(a[2]-b[2])**2}
function generateImportedLayer(){
  if(importDraft.value)return saveImportedCrop()
  const url=pendingImageUrl.value;if(!url)return
  const image=new Image();image.onload=()=>{
    const w=Math.max(8,Math.min(180,Math.round(convertWidth.value))),h=Math.max(8,Math.min(180,Math.round(w*image.height/image.width))),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h
    const ctx=canvas.getContext('2d')!;ctx.imageSmoothingEnabled=generationStyle.value==='realistic';ctx.drawImage(image,0,0,w,h)
    const data=ctx.getImageData(0,0,w,h).data,sourceRgb:Array<number[]|null>=[],counts=new Map<string,number>(),corners=[[0,0],[w-1,0],[0,h-1],[w-1,h-1]],background=[0,1,2].map(channel=>Math.round(corners.reduce((sum,[x,y])=>sum+data[(y*w+x)*4+channel],0)/4))
    for(let i=0;i<w*h;i++){if(data[i*4+3]<40){sourceRgb.push(null);continue}let rgb=[data[i*4],data[i*4+1],data[i*4+2]];if(backgroundMode.value==='remove'&&Math.sqrt(distance(rgb,background))<=backgroundTolerance.value){sourceRgb.push(null);continue}if(generationStyle.value==='cartoon')rgb=rgb.map(value=>Math.round(value/20)*20);sourceRgb.push(rgb);let best=palette[0],bestDistance=Infinity;for(const item of palette){const value=distance(rgb,rgbOf(item.hex));if(value<bestDistance){bestDistance=value;best=item}}counts.set(best.code,(counts.get(best.code)??0)+1)}
    const candidateCodes=[...counts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,Math.max(2,Math.min(48,maxColors.value))).map(([code])=>code),candidates=palette.filter(item=>candidateCodes.includes(item.code)),generated=sourceRgb.map(rgb=>{if(!rgb)return null;let best=candidates[0]??palette[0],bestDistance=Infinity;for(const item of candidates){const value=distance(rgb,rgbOf(item.hex));if(value<bestDistance){bestDistance=value;best=item}}return best.code}),used=new Set(generated.filter(Boolean)).size
    importDraft.value={width:w,height:h,cells:generated,colors:used};resetCrop();importMenuOpen.value=false;showToast('拼豆预览已放入拼豆板，请框选保留区域')
  };image.src=url
}
function cancelImportedCrop(){importDraft.value=null;resetCrop();showToast('已取消导入剪裁')}
function addBeadLayer(){if(!rawProject.value)return;const layer:ProjectLayer={id:crypto.randomUUID(),name:`拼豆层 ${layers.value.filter(item=>item.type==='bead').length+1}`,type:'bead',visible:true,locked:false,opacity:1,cells:Array(rawProject.value.width*rawProject.value.height).fill(null)};saveLayers([...layers.value,layer],layer.id);newLayerMenu.value=false}
function chooseReferenceLayer(){referenceInput.value?.click();newLayerMenu.value=false}
function addReferenceLayer(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!rawProject.value)return;const layer:ProjectLayer={id:crypto.randomUUID(),name:file.name.replace(/\.[^.]+$/,''),type:'reference',visible:true,locked:false,opacity:.35,cells:Array(rawProject.value.width*rawProject.value.height).fill(null),imageUrl:URL.createObjectURL(file)};saveLayers([...layers.value,layer],layer.id);(event.target as HTMLInputElement).value=''}
function patchLayer(id:string,patch:Partial<ProjectLayer>){saveLayers(layers.value.map(layer=>layer.id===id?{...layer,...patch}:layer),rawProject.value!.activeLayerId)}
async function deleteLayer(layer:ProjectLayer){if(layers.value.length===1)return showToast('至少保留一个图层');try{await showConfirmDialog({title:`删除「${layer.name}」？`,message:'图层内容删除后无法恢复。',confirmButtonText:'确认删除'});const next=layers.value.filter(item=>item.id!==layer.id);const active=rawProject.value!.activeLayerId===layer.id?(next.find(item=>item.type==='bead')?.id??next[0].id):rawProject.value!.activeLayerId;saveLayers(next,active)}catch{}layerMenuId.value=null}
function closeTransient(){openToolGroup.value=null;importMenuOpen.value=false;paletteExpanded.value=false;tool.value='pan';pendingMove.value=null}
function selectLayer(layer:ProjectLayer){closeTransient();saveLayers(layers.value,layer.id);layerMenuId.value=null}
function toggleLayerMenu(layer:ProjectLayer){
  const shouldOpen=layerMenuId.value!==layer.id
  saveLayers(layers.value,layer.id)
  layerMenuId.value=shouldOpen?layer.id:null
}
function dropLayer(targetId:string){if(!draggedLayerId.value||draggedLayerId.value===targetId)return;const next=[...layers.value],from=next.findIndex(layer=>layer.id===draggedLayerId.value),to=next.findIndex(layer=>layer.id===targetId),[moved]=next.splice(from,1);next.splice(to,0,moved);saveLayers(next);draggedLayerId.value=null}
onMounted(()=>{document.body.classList.add('studio-locked');document.addEventListener('pointerdown',handleOutside);if(!project.value)return router.replace('/');widthDraft.value=project.value.width;heightDraft.value=project.value.height;selectedPreset.value=[52,78,104,156].includes(project.value.width)&&project.value.width===project.value.height?`${project.value.width}x${project.value.height}`:'';const url=sessionStorage.getItem(`pocket-pin:import:${project.value.id}`);if(url){sessionStorage.removeItem(`pocket-pin:import:${project.value.id}`);pendingImageUrl.value=url;pendingImageName.value=project.value.name;generatedLayerName.value=project.value.name;convertWidth.value=project.value.width;importMenuOpen.value=true}})
onUnmounted(()=>{document.body.classList.remove('studio-locked');document.removeEventListener('pointerdown',handleOutside)})
</script>

<template><app-shell v-if="project" :title="project.name" back @back="router.push('/')" @title-click="renameCurrent">
  <template #center><div class="board-size title-board-size"><b>拼豆板</b><input v-model.number="widthDraft" aria-label="画布宽度" type="number" min="8" max="180" @input="syncWidth" @change="changeWidth"><button class="ratio-lock" :class="{active:ratioLocked}" :aria-label="ratioLocked?'解除宽高比锁定':'锁定宽高比'" :title="ratioLocked?'已锁定原始宽高比':'宽高可独立修改'" @click="ratioLocked=!ratioLocked"><lock-glyph :locked="ratioLocked"/></button><input v-model.number="heightDraft" aria-label="画布高度" type="number" min="8" max="180" @input="syncHeight" @change="changeHeight"><label class="size-select"><select v-model="selectedPreset" aria-label="常用画布尺寸" @change="choosePreset"><option value="">常用尺寸</option><option value="52x52">52 × 52</option><option value="78x78">78 × 78</option><option value="104x104">104 × 104</option><option value="156x156">156 × 156</option></select><van-icon name="arrow-down"/></label><button title="应用新的画布尺寸" @click="resize">应用</button></div></template>
  <template #actions><div class="header-actions"><button class="danger-action" title="清空当前拼豆层" @click="clearAll"><van-icon name="delete-o"/><span>清空</span></button><button :disabled="!history.length" :data-history-count="history.length" title="撤销上一步编辑" @click="undo"><van-icon name="revoke"/><span>撤销</span></button><button :disabled="!future.length" title="重做已撤销的编辑" @click="redo"><van-icon name="replay"/><span>重做</span></button><button class="primary" title="导出当前 PNG 图纸" @click="exportPng"><van-icon name="down"/><span>导出图纸</span></button><button class="icon-button mobile-panel-button" title="打开图层" @click="layersOpen=!layersOpen"><van-icon name="cluster-o"/></button><button class="icon-button mobile-panel-button" title="打开右侧面板" @click="panelOpen=!panelOpen"><van-icon name="setting-o"/></button></div></template>
  <div class="editor-toolbar">
    <div class="tool-groups">
      <button class="tool-group-trigger" :class="{active:tool==='pan'}" title="拖动或滚动查看大画布" @click="activateTool('pan')"><tool-glyph name="pan"/><span>拖动</span></button>
      <div class="tool-group"><button class="tool-group-trigger" :class="{active:drawToolIds.includes(tool)}" title="绘制、形状和填色工具" @click="toggleToolGroup('draw')"><tool-glyph name="pencil"/><span>编辑</span><van-icon name="arrow-down"/></button><div v-if="openToolGroup==='draw'" class="tool-popover"><button v-for="item in tools.filter(item=>drawToolIds.includes(item.id))" :key="item.id" :class="{active:tool===item.id}" :title="`${item.label}：${toolHint(item.id)}`" @click="activateTool(item.id)"><tool-glyph :name="item.id"/><span>{{item.label}}</span></button></div></div>
      <div class="tool-group"><button class="tool-group-trigger" :class="{active:selectToolIds.includes(tool)}" title="矩形选区工具" @click="toggleToolGroup('select')"><tool-glyph name="move"/><span>选区</span><van-icon name="arrow-down"/></button><div v-if="openToolGroup==='select'" class="tool-popover"><button v-for="item in tools.filter(item=>selectToolIds.includes(item.id))" :key="item.id" :class="{active:tool===item.id}" :title="item.id==='paste'?'点击位置放下已复制内容':'沿对角线拖出矩形选区'" @click="activateTool(item.id)"><tool-glyph :name="item.id"/><span>{{item.label}}</span></button></div></div>
      <div class="tool-group import-tool-group"><button class="tool-group-trigger" :class="{active:importMenuOpen}" title="从设备选择图片并配置生成图纸" @click="pendingImageUrl?importMenuOpen=!importMenuOpen:selectImage()"><tool-glyph name="import"/><span>导入</span><van-icon name="arrow-down"/></button><input ref="fileInput" class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp" @change="loadFile"><div v-if="importMenuOpen" class="import-config-popover"><div class="import-preview" @click="selectImage"><img v-if="pendingImageUrl" :src="pendingImageUrl" alt="导入原图完整预览"><span><b>{{pendingImageName||'选择图片'}}</b><small>完整原图预览 · 点击更换</small></span></div><div class="import-config-grid"><label><span>目标宽度</span><input v-model.number="convertWidth" type="number" min="8" max="180"></label><label class="range-field"><span>色数上限 <b>{{maxColors}}</b></span><input v-model.number="maxColors" type="range" min="2" max="48" step="1"></label><label><span>生成风格</span><select v-model="generationStyle"><option value="cartoon">卡通</option><option value="realistic">写实</option></select></label><label><span>背景方式</span><select v-model="backgroundMode"><option value="keep">保留背景</option><option value="remove">移除背景</option></select></label><label v-if="backgroundMode==='remove'" class="range-field full"><span>去背景容差 <b>{{backgroundTolerance}}</b></span><input v-model.number="backgroundTolerance" type="range" min="0" max="120"></label><label class="full"><span>图层名称</span><input v-model="generatedLayerName" maxlength="36" placeholder="例如：头像"></label></div><button class="generate-layer-button" :disabled="!pendingImageUrl" @click="generateImportedLayer">生成完整拼豆预览</button></div></div>
    </div>
    <div class="toolbar-balance"></div>
  </div>
  <div v-if="tool==='recolor'" class="recolor-mode-bar"><span>换色范围</span><button :class="{active:recolorMode==='single'}" @click="recolorMode='single'">单个拼豆</button><button :class="{active:recolorMode==='same'}" @click="recolorMode='same'">相同色号批量</button></div>
  <main class="studio-page figma-studio">
    <aside :class="['layers-sidebar',{open:layersOpen}]">
      <div class="layers-header"><div><b>图层</b><span>{{layers.length}}</span></div><button aria-label="新建图层" @click="newLayerMenu=!newLayerMenu"><van-icon name="plus"/></button><div v-if="newLayerMenu" class="new-layer-menu"><button @click="addBeadLayer"><van-icon name="apps-o"/><span><b>拼豆层</b><small>可绘制与统计用量</small></span></button><button @click="chooseReferenceLayer"><van-icon name="photo-o"/><span><b>照片参考层</b><small>仅作为辅助底图</small></span></button></div><input ref="referenceInput" class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp" @change="addReferenceLayer"></div>
      <button class="workspace-preview" title="打开完整图纸预览" @click="previewOpen=true"><mini-preview :width="project.width" :height="project.height" :cells="visibleCells"/></button>
      <div class="layers-list"><article v-for="layer in [...layers].reverse()" :key="layer.id" draggable="true" :class="['figma-layer',{active:layer.id===rawProject?.activeLayerId,hidden:!layer.visible}]" @click="selectLayer(layer)" @dragstart="draggedLayerId=layer.id" @dragover.prevent @drop="dropLayer(layer.id)"><div class="layer-thumb"><van-icon :name="layer.type==='bead'?'apps-o':'photo-o'"/></div><div class="layer-name"><b>{{layer.name}}</b><small>{{layer.type==='bead'?`${layer.cells.filter(Boolean).length} 颗拼豆`:'照片参考'}}</small></div><button :aria-label="layer.visible?'隐藏图层':'显示图层'" @click.stop="patchLayer(layer.id,{visible:!layer.visible})"><van-icon :name="layer.visible?'eye-o':'closed-eye'"/></button><button :class="['layer-lock',{locked:layer.locked}]" :aria-label="layer.locked?'解锁图层':'锁定图层'" @click.stop="patchLayer(layer.id,{locked:!layer.locked})"><lock-glyph :locked="layer.locked"/></button><button class="layer-delete" aria-label="删除图层" @click.stop="deleteLayer(layer)"><van-icon name="delete-o"/></button></article></div>
    </aside>
    <section class="canvas-area"><div class="canvas-info"><b>{{importDraft?`${importDraft.width} × ${importDraft.height}`:`${project.width} × ${project.height}`}}</b><span v-if="importDraft">剪裁拼豆预览</span><template v-else><span>{{visibleCells.filter(Boolean).length}} 颗</span><span>网格 {{project.width * project.height}} 格</span><span>自动保存</span></template></div><div v-if="importDraft" class="canvas-scroll import-board-crop"><div class="board-crop-stage" :style="{aspectRatio:`${importDraft.width} / ${importDraft.height}`}" @pointerdown="cropStart" @pointermove="cropMove" @pointerup="cropStop" @pointercancel="cropStop"><mini-preview detailed :width="importDraft.width" :height="importDraft.height" :cells="importDraft.cells"/><div class="crop-selection" :style="{width:`${100/cropZoom}%`,height:`${100/cropZoom}%`,left:`${(100-100/cropZoom)*(cropX+1)/2}%`,top:`${(100-100/cropZoom)*(cropY+1)/2}%`}"><div class="crop-grid"></div><i class="crop-corner tl"></i><i class="crop-corner tr"></i><i class="crop-corner bl"></i><i class="crop-corner br"></i></div></div><div class="board-crop-actions"><button @click="cancelImportedCrop">取消</button><label>剪裁范围 <b>{{Math.round(100/cropZoom)}}%</b><input v-model.number="cropZoom" type="range" min="1" max="3" step=".05"></label><button class="primary" @click="saveImportedCrop">按选区创建图层</button></div></div><div v-else class="canvas-scroll" @wheel.prevent="zoomAtPointer"><div class="canvas-scale layer-canvas-stack"><img v-for="layer in layers.filter(item=>item.type==='reference'&&item.visible&&item.imageUrl)" :key="layer.id" class="reference-layer-image" :src="layer.imageUrl" :style="{opacity:layer.opacity}"><bead-canvas :project="project" :layers="layers" :tool="tool" :color="color" :grid="grid" :coordinates="coordinates" :round="round" :zoom="zoom" :board-tone="boardTone" :recolor-mode="recolorMode" :move-pending="Boolean(pendingMove)" :selected-ids="pendingMove?.ids??[]" :locked="activeLayer?.locked||activeLayer?.type!=='bead'" @change="change" @pick="pick" @focus="focusBead" @action="canvasAction" @range="rangeAction"/></div></div></section>
    <aside class="studio-panel pro-panel" :class="{open:panelOpen}"><div class="panel-tabs two"><button :class="{active:panel==='adjust'}" @click="panel='adjust'">属性</button><button :class="{active:panel==='usage'}" @click="panel='usage'">用量</button></div><template v-if="panel==='usage'"><div class="usage-total"><strong>{{visibleCells.filter(Boolean).length}}</strong><span>总颗数 · {{usage.length}} 种颜色</span></div><div class="usage-compact"><div v-for="row in usage" :key="row.color.code"><i :style="{background:row.color.hex,color:readableColor(row.color.hex)}"><b>{{row.color.code}}</b></i><span>× {{row.count}}</span></div></div></template><template v-else><div class="property-list"><div><span><b><van-icon name="apps-o"/>定位网格</b><small>缩小后自动弱化或隐藏</small></span><div class="segmented-toggle"><button :class="{active:!grid}" @click="grid=false">关闭</button><button :class="{active:grid}" @click="grid=true">开启</button></div></div><div><span><b><van-icon name="label-o"/>显示坐标</b><small>在豆板边缘标注编号</small></span><div class="segmented-toggle"><button :class="{active:!coordinates}" @click="coordinates=false">关闭</button><button :class="{active:coordinates}" @click="coordinates=true">开启</button></div></div><div><span><b><van-icon name="gem-o"/>预览形状</b><small>切换工作区拼豆外观</small></span><div class="segmented-toggle"><button :class="{active:!round}" @click="round=false">方豆</button><button :class="{active:round}" @click="round=true">圆豆</button></div></div><div><span><b><van-icon name="brush-o"/>豆板底色</b><small>切换浅色或深色豆板</small></span><div class="segmented-toggle"><button :class="{active:boardTone==='light'}" @click="boardTone='light'">白色</button><button :class="{active:boardTone==='dark'}" @click="boardTone='dark'">黑色</button></div></div><template v-if="activeLayer"><div><span><b><van-icon name="eye-o"/>图层透明度</b><small>拖动时查看数值</small></span><label class="opacity-control"><output v-if="opacityBubble!==null">{{opacityBubble}}%</output><input :value="activeLayer.opacity" type="range" min="0" max="1" step=".01" @input="setOpacity(activeLayer,$event)" @change="opacityBubble=null"></label></div><div v-if="activeLayer.type==='bead'" class="mirror-row"><span><b><van-icon name="exchange"/>镜像</b><small>翻转当前拼豆图层</small></span><div><button title="左右镜像" @click="mirror(true)"><van-icon name="exchange"/>左右</button><button title="上下镜像" @click="mirror(false)"><van-icon name="exchange" class="vertical-icon"/>上下</button></div></div></template></div></template></aside>
    <div v-if="activeLayer?.type==='bead'&&!activeLayer.locked&&['pencil','fill','recolor','text','eyedropper'].includes(tool)" :class="['bottom-palette',{expanded:paletteExpanded,recommending:tool==='recolor'&&recommendedColors.length}]"><div v-if="tool==='recolor'&&recommendedColors.length" class="recommended-swatches"><span>推荐相近色</span><button v-for="item in recommendedColors" :key="item.code" :title="`${item.code} ${item.name}`" @click="chooseRecommended(item.code)"><i :style="{background:item.hex}"></i><b>{{item.code}}</b></button></div><button class="palette-eyedropper" :class="{active:tool==='eyedropper'}" title="从画布吸取单个拼豆颜色，完成后返回当前工具" @click="activateTool('eyedropper')"><tool-glyph name="eyedropper"/></button><div class="palette-divider"></div><div class="palette-head"><button class="current-swatch" @click="paletteExpanded=!paletteExpanded"><i :style="{background:colorByCode(color)?.hex}"></i><b>{{color}}</b><span class="fold-icon"><van-icon :name="paletteExpanded?'arrow-down':'arrow-up'"/></span></button><div v-if="paletteExpanded" class="palette-groups"><button v-for="group in groups" :key="group" :class="{active:paletteGroup===group}" @click="paletteGroup=group">{{group}}</button></div></div><div class="quick-swatches"><button v-for="item in (paletteExpanded?filteredPalette:filteredPalette.slice(0,12))" :key="item.code" :aria-label="`${item.code} ${item.name}`" :class="{active:item.code===color}" @click="color=item.code"><i :style="{background:item.hex}"></i><span>{{item.code}}</span></button></div></div>
    <div v-if="pendingMove" class="move-confirm"><span><van-icon name="upgrade"/>选区已浮起</span><button @click="pendingMove=null">完成移动</button></div>
    <van-popup v-model:show="resizeOpen" teleport="body" class="resize-dialog"><button class="preview-close" aria-label="关闭" @click="resizeOpen=false"><van-icon name="cross"/></button><h3>调整拼豆板</h3><p>{{project.width}} × {{project.height}} → <b>{{widthDraft}} × {{heightDraft}}</b></p><div class="resize-stage-wrap"><div class="resize-preview" :style="{aspectRatio:`${widthDraft} / ${heightDraft}`,width:`${widthDraft>=heightDraft?280:280*widthDraft/heightDraft}px`}" @pointerdown="resizeDragStart" @pointermove="resizeDragMove" @pointerup="resizeDragStop" @pointercancel="resizeDragStop"><div class="resize-content" :style="{width:`${project.width/widthDraft*100}%`,height:`${project.height/heightDraft*100}%`,left:`${resizeOffsetX/widthDraft*100}%`,top:`${resizeOffsetY/heightDraft*100}%`}"><mini-preview :width="project.width" :height="project.height" :cells="visibleCells"/></div></div></div><span class="resize-hint"><van-icon name="upgrade"/>拖动已有内容，调整它在新画板中的位置</span><div class="resize-actions"><button @click="resizeOpen=false">取消</button><button class="primary" @click="applyResize">应用并裁剪</button></div></van-popup>
    <van-popup v-model:show="previewOpen" teleport="body" class="preview-dialog"><button class="preview-close" aria-label="关闭预览" @click="previewOpen=false"><van-icon name="cross"/></button><h3>{{project.name}}</h3><div><mini-preview detailed :width="project.width" :height="project.height" :cells="visibleCells"/></div><p>{{project.width}} × {{project.height}} · {{usage.length}} 色 · {{visibleCells.filter(Boolean).length}} 颗</p></van-popup>
    <van-popup v-model:show="layerSheetOpen" position="bottom" round teleport="body" :lock-scroll="false" class="more-sheet"><div v-if="menuLayer" class="sheet-content"><div class="sheet-handle"></div><h3>{{menuLayer.name}}</h3><label class="sheet-opacity">不透明度<input :value="menuLayer.opacity" type="range" min="0" max="1" step=".01" @input="setOpacity(menuLayer,$event)" @change="opacityBubble=null"></label><div v-if="menuLayer.type==='bead'" class="sheet-actions mirror-sheet-actions"><button @click="mirror(true);layerSheetOpen=false"><van-icon name="exchange"/>左右镜像</button><button @click="mirror(false);layerSheetOpen=false"><van-icon name="exchange" class="vertical-icon"/>上下镜像</button></div><button class="sheet-danger" @click="deleteLayer(menuLayer)"><van-icon name="delete-o"/>删除图层</button></div></van-popup>
  </main></app-shell></template>
